      SUBROUTINE DFRINBCC     CALCULATES PARTIAL DERIVATIVES OF BENDING MAGNET FRINGEC     FIELD MATRIX ELEMENTS WITH RESPECT TO CENTRAL MAGNETICC     FIELD OR ANYTHING EQUIVALENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      INTEGER  IANG, IB, IL, IRHO      REAL  HVCC--------------------------------------------------------------      LINEAR = .FALSE.      IL = IPTOJB(NL)      IB = IPTOJB(NBV)      IRHO = IPTOJB(NRHO)      IANG = IPTOJB(NANG)      IF (IL .NE. 0 .AND. IANG .NE. 0) HV = H0*UNITI(7)*DPARM/AL      IF (IB .NE. 0) HV = UNITI(9)*DPARM/PREF      IF (IRHO .NE. 0) HV = - H0**2*DPARM*UNITI(8)      RV(2,1) = HV*TB      RV(4,3) = - HV*TB + 4.0*HV*H0*APB(2)*LAYL*SB*(SB**2 + TB**2)      RETURN      END